import { Component, EventEmitter, Input, Output } from '@angular/core';

@Component({
  selector: 'app-pagination',
  templateUrl: './pagination.component.html',
  styleUrls: ['./pagination.component.css']
})
export class PaginationComponent {
  @Input() totalItems = 0;
  @Input() pageSize = 10;
  @Input() page = 1;
  @Output() pageChange = new EventEmitter<number>();
  @Output() pageSizeChange = new EventEmitter<number>();

  readonly pageSizes = [5, 10, 20, 50];

  get totalPages(): number { return Math.max(1, Math.ceil(this.totalItems / this.pageSize)); }
  get startItem(): number { return this.totalItems === 0 ? 0 : (this.page - 1) * this.pageSize + 1; }
  get endItem(): number { return Math.min(this.totalItems, this.page * this.pageSize); }
  get pages(): number[] {
    const max = 7;
    if (this.totalPages <= max) return Array.from({ length: this.totalPages }, (_, i) => i + 1);
    const result = [1];
    const from = Math.max(2, this.page - 2);
    const to = Math.min(this.totalPages - 1, this.page + 2);
    if (from > 2) result.push(-1);
    for (let p = from; p <= to; p++) result.push(p);
    if (to < this.totalPages - 1) result.push(-1);
    result.push(this.totalPages);
    return result;
  }
  goTo(p: number): void { if (p >= 1 && p <= this.totalPages && p !== this.page) this.pageChange.emit(p); }
  changeSize(size: string): void { this.pageSizeChange.emit(Number(size)); }
}
<div class="pagination-wrap">
  <div class="summary">{{ startItem }}-{{ endItem }} Out of {{ totalItems }}</div>
  <div class="controls">
    <button class="arrow" [disabled]="page === 1" (click)="goTo(page - 1)" aria-label="Previous page"><</button>
    <ng-container *ngFor="let p of pages">
      <span *ngIf="p === -1" class="ellipsis">…</span>
      <button *ngIf="p !== -1" class="page" [class.active]="p === page" (click)="goTo(p)">{{ p }}</button>
    </ng-container>
    <button class="arrow" [disabled]="page === totalPages" (click)="goTo(page + 1)" aria-label="Next page">></button>
  </div>
  <label class="page-size">Items per page <select [value]="pageSize" (change)="changeSize($any($event.target).value)"><option *ngFor="let size of pageSizes" [value]="size">{{ size }}</option></select></label>
</div>
